Plan:
- Read the country list from column A above the company table and the country headers from the company table’s header row.
- For each company row, count how many listed countries have a corresponding employee value greater than 0.
- Write those counts as plain integers into the “No of countries” column for the company rows.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title]

def clean(v):
    if v is None:
        return ""
    return str(v).strip()

# Find the company table header row, e.g. row 11 where A = "Company"
header_row = None
for r in range(1, vws.max_row + 1):
    if clean(vws.cell(row=r, column=1).value).lower() == "company":
        header_row = r
        break

if header_row is None:
    header_row = 11

# Find the answer column, e.g. "No of countries"
ans_col = None
for c in range(1, vws.max_column + 1):
    if clean(vws.cell(row=header_row, column=c).value).lower() == "no of countries":
        ans_col = c
        break

if ans_col is None:
    ans_col = 9

# Read the separate country list from column A above the company table.
top_countries = []
seen = set()
for r in range(2, header_row):
    s = clean(vws.cell(row=r, column=1).value)
    if not s:
        continue
    key = s.lower()
    if key not in seen:
        seen.add(key)
        top_countries.append(s)

# Read country headers from the company table.
country_cols = []
for c in range(2, vws.max_column + 1):
    s = clean(vws.cell(row=header_row, column=c).value)
    if not s:
        continue
    if s.lower() == "no of countries":
        break
    country_cols.append((c, s))

col_by_name = {name.lower(): c for c, name in country_cols}

def is_positive(v):
    if isinstance(v, bool):
        return False
    if isinstance(v, (int, float)):
        return v > 0
    if isinstance(v, str):
        try:
            return float(v.strip()) > 0
        except Exception:
            return False
    return False

# Company rows are below the header row and have a non-empty company name.
company_rows = []
for r in range(header_row + 1, vws.max_row + 1):
    if clean(vws.cell(row=r, column=1).value):
        company_rows.append(r)

# Fallback if detection fails: use the expected answer rows.
if not company_rows:
    company_rows = [r for r in range(12, 14) if clean(vws.cell(row=r, column=1).value)]

for r in company_rows:
    if top_countries:
        count = 0
        for country in top_countries:
            c = col_by_name.get(country.lower())
            if c is not None and is_positive(vws.cell(row=r, column=c).value):
                count += 1
    else:
        # If no separate country list is found, count all country columns with > 0.
        count = sum(
            1
            for c, _ in country_cols
            if is_positive(vws.cell(row=r, column=c).value)
        )

    ws.cell(row=r, column=ans_col).value = int(count)
    print(f"row={r}, company={clean(vws.cell(row=r, column=1).value)}, count={count}")

wb.save(OUT)
```

